*{box-sizing:border-box} :root{--ink:#17231f;--muted:#75817b;--cream:#f3f1e8;--paper:#fbfaf5;--green:#204a3b;--lime:#d8e56a;--line:#e6e5dc;--orange:#d38745} html,body{margin:0;min-height:100%;background:#e8e8dd;color:var(--ink);font-family:'DM Sans',sans-serif}body{min-height:100dvh;padding:18px;display:grid;place-items:center}.game-shell{width:min(1320px,100%);background:var(--paper);min-height:min(850px,calc(100dvh - 36px));padding:0 34px 0;box-shadow:0 20px 70px #25342b1b;border:1px solid #ffffff;border-radius:4px;display:flex;flex-direction:column}.topbar{height:74px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;flex:none}.brand{display:flex;align-items:center;gap:11px;text-decoration:none;color:var(--ink)}.brand-mark{width:32px;height:32px;display:grid;place-items:center;border:1.5px solid var(--green);border-radius:50%;font-family:'Playfair Display';font-size:20px;position:relative;color:var(--green)}.brand-mark span{position:absolute;font-family:sans-serif;font-size:8px;top:3px;right:3px}.brand-name{font-size:12px;letter-spacing:1.7px;font-weight:800}.brand-name i{font-style:normal;color:#a6a99a;margin:0 3px}.top-meta{display:flex;align-items:center;gap:27px}.session-pill,.coin-wallet{font-family:'DM Mono',monospace;font-size:9px;letter-spacing:1.15px;color:#78817a;display:flex;align-items:center;gap:8px}.live-dot{height:7px;width:7px;background:#93ad6a;border-radius:50%;box-shadow:0 0 0 3px #93ad6a22}.session-num{color:#a1a79d}.coin-wallet{gap:7px}.coin-wallet strong{font-family:'DM Sans';font-size:17px;color:var(--ink);letter-spacing:0}.coin-icon{color:#c9973b;font-size:20px}.game-layout{display:grid;grid-template-columns:minmax(0,1.72fr) minmax(320px,.82fr);gap:30px;padding:27px 0 24px;flex:1;align-items:stretch;min-height:0}.range-panel{display:flex;flex-direction:column;min-width:0}.scene-head{height:59px;display:flex;justify-content:space-between;align-items:flex-start}.eyebrow{font-family:'DM Mono',monospace;font-size:9px;letter-spacing:1.55px;font-weight:500;color:#78877b;display:block}.eyebrow-line{display:inline-block;width:17px;height:1px;background:#a9b5a0;vertical-align:middle;margin:0 8px 3px 0}.scene-head h1{font-family:'Playfair Display',serif;font-size:27px;font-weight:600;line-height:1.2;margin:5px 0 0;letter-spacing:-.4px}.scene-head h1 em,.card h2 em,.modal h2 em{font-weight:600;color:#758c68}.area-switch{border:1px solid var(--line);background:transparent;height:32px;padding:0 11px;color:#607067;font-family:'DM Mono',monospace;font-size:9px;letter-spacing:.6px;display:flex;align-items:center;gap:8px;cursor:pointer}.area-switch b{font-size:14px;font-weight:400;margin-left:3px}.scene-wrap{position:relative;overflow:hidden;flex:1;min-height:350px;background:#b9c9b0;touch-action:none;cursor:crosshair}.scene-wrap canvas{display:block;width:100%;height:100%;touch-action:none}.scene-vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,#0d27150b,transparent 30%,transparent 75%,#1d352538),linear-gradient(90deg,#16281810,transparent 16%,transparent 88%,#15291b14)}.distance-tag{position:absolute;top:17px;left:18px;color:#fff;text-shadow:0 1px 5px #1a2e2480;display:grid;grid-template-columns:16px auto;align-items:center;column-gap:4px}.distance-icon{font-size:15px;grid-row:span 2;color:#edf1d3}.distance-tag span:nth-child(2){font:500 17px 'DM Mono';line-height:19px}.distance-tag small{font:8px 'DM Mono';letter-spacing:1px;opacity:.82}.wind-widget{position:absolute;right:15px;top:15px;width:132px;padding:10px 11px 9px;background:#172a21bb;border:1px solid #ffffff38;color:#fff;backdrop-filter:blur(5px)}.wind-title{display:flex;justify-content:space-between;font:9px 'DM Mono';letter-spacing:1.15px;color:#d9e3ce}.wind-status{font-size:7px;letter-spacing:.6px;color:#b9d17b}.wind-status i{display:inline-block;width:5px;height:5px;border-radius:50%;background:#c9dc71;margin-right:4px;vertical-align:1px}.wind-readout{display:flex;align-items:baseline;gap:6px;margin-top:3px}.wind-arrow{font-size:17px;color:#dce89c;transition:transform .5s}.wind-readout strong{font:500 22px 'DM Mono';letter-spacing:-1px}.wind-readout small{font:9px 'DM Mono';color:#cad2c3}.wind-gauge{height:4px;background:#ffffff30;margin:6px 0 5px;position:relative;display:flex;justify-content:space-between}.wind-gauge span{position:absolute;left:0;top:0;height:100%;width:40%;background:#d6e47b;transition:width .5s}.wind-gauge i{height:7px;width:1px;background:#ffffff66;position:relative;top:-2px}.wind-direction{font:7px 'DM Mono';letter-spacing:.8px;color:#c5d2c0}.scene-hint{position:absolute;bottom:40px;left:50%;transform:translateX(-50%);color:#fff;font:8px 'DM Mono';letter-spacing:1.2px;text-shadow:0 1px 4px #203a2b;white-space:nowrap;opacity:.8;pointer-events:none;transition:opacity .5s}.scene-hint span{font-size:14px;vertical-align:-2px;margin-right:5px}.scene-hint.hidden{opacity:0}.scene-footer{position:absolute;left:15px;right:15px;bottom:12px;display:flex;justify-content:space-between;color:#fff;font:8px 'DM Mono';letter-spacing:.9px;text-shadow:0 1px 4px #172f23;pointer-events:none}.scene-footer b{color:#cadf93}.sun-icon{font-size:12px;vertical-align:-1px;margin-right:5px;color:#f8df9b}.result-stamp{position:absolute;top:49%;left:50%;transform:translate(-50%,-50%) scale(.8);padding:10px 18px 9px;background:#f8f6e9ed;color:#244b3a;text-align:center;opacity:0;transition:.3s;pointer-events:none;box-shadow:0 5px 18px #173a2c2e;border:1px solid #fff9}.result-stamp.visible{opacity:1;transform:translate(-50%,-50%) scale(1)}.result-stamp span{display:block;font-size:17px;color:#bb9147}.result-stamp strong{display:block;font:800 13px 'DM Sans';letter-spacing:2px}.result-stamp small{display:block;font:8px 'DM Mono';letter-spacing:1.5px;color:#728376;margin-top:2px}.shot-flash{position:absolute;inset:0;background:#fff8ce;opacity:0;pointer-events:none}.shot-flash.active{animation:flash .28s}@keyframes flash{0%{opacity:.55}100%{opacity:0}}.range-caption{height:38px;display:flex;justify-content:space-between;align-items:center;color:#8c958d;font:8px 'DM Mono';letter-spacing:1.05px}.range-caption b{color:#42564a;font-weight:500}.caption-sep{color:#c7c9bd;margin:0 7px}.caption-center{color:#859187}.pulse-dot{display:inline-block;width:5px;height:5px;background:#97ae72;border-radius:50%;margin-left:5px;vertical-align:1px;box-shadow:0 0 0 3px #97ae7220}.score-label{color:#a0a69e}.score-label b{margin-left:7px;color:#43594a}.side-panel{display:flex;flex-direction:column;gap:13px;min-width:0}.card{border:1px solid var(--line);padding:17px 18px;background:#fffefa}.card-heading,.gear-head{display:flex;justify-content:space-between;align-items:flex-start}.card h2{font:600 19px 'Playfair Display';margin:5px 0 0;letter-spacing:-.2px}.challenge-mark{font:11px 'DM Mono';color:#9ba496;border:1px solid var(--line);width:25px;height:25px;display:grid;place-items:center}.target-copy{font-size:10px;line-height:1.5;color:#7c857d;margin:8px 0 14px;max-width:260px}.target-diagram{display:flex;align-items:center;justify-content:space-between;background:#f6f5ee;padding:10px 14px;margin-bottom:13px}.mini-target{height:60px;width:60px;border-radius:50%;position:relative;background:repeating-radial-gradient(circle,#f9f8ef 0 6px,#768c68 6.5px 7.5px,#f9f8ef 8px 13px,#b6664c 13.5px 15px);border:1px solid #d5d3c6;box-shadow:0 2px 4px #24382720}.mini-target:after{content:'';position:absolute;inset:0;border-radius:50%;background:repeating-radial-gradient(circle,transparent 0 11px,#f4f2e7 11.5px 12.5px);opacity:.9}.mini-target b{position:absolute;z-index:1;left:50%;top:50%;transform:translate(-50%,-50%);width:6px;height:6px;background:#d6a64f;border-radius:50%;border:1px solid #fff4}.target-key{display:flex;flex-direction:column;gap:10px;min-width:143px}.target-key>div{display:grid;grid-template-columns:9px 1fr auto;align-items:center;gap:6px;font:7px 'DM Mono';letter-spacing:.5px;color:#7a8179}.target-key strong{font:600 10px 'DM Sans';letter-spacing:0;color:#3d5b47}.target-key strong small{font-size:8px;font-weight:400;color:#899187}.key-dot{width:7px;height:7px;border-radius:50%;background:#78906c}.key-dot.bull{background:#d2a64e}.accuracy-row{display:flex;align-items:center;gap:8px;font:7px 'DM Mono';letter-spacing:.65px;color:#899289}.accuracy-meter{flex:1;height:3px;background:#eeeee7}.accuracy-meter i{display:block;width:0;height:100%;background:#8aa270;transition:width .3s}.accuracy-row b{font:9px 'DM Mono';color:#506550}.gear-card{padding:16px 18px 12px}.gear-head{align-items:center;margin-bottom:8px}.gear-head h2{margin-top:4px}.icon-button{width:27px;height:27px;border:1px solid var(--line);background:#fff;color:#657466;font-size:14px;cursor:pointer}.gear-row{display:grid;grid-template-columns:33px minmax(90px,1fr) auto;gap:9px;align-items:center;padding:11px 0;border-top:1px solid #eeeeea}.gear-icon{width:30px;height:30px;display:grid;place-items:center;background:#f2f3eb;color:#547251;font-size:24px}.arrow-icon{font-size:19px}.gear-info{min-width:0}.gear-info strong{display:block;font-size:10px;font-weight:700;color:#35443a;white-space:nowrap}.gear-info small{display:block;font:7px 'DM Mono';letter-spacing:.4px;color:#92988f;margin-top:4px;white-space:nowrap}.gear-info small b{color:#637664;font-weight:500}.gear-info small span{padding:0 3px;color:#c2c5bc}.upgrade-button{border:1px solid #dce1d4;background:#f7f8f2;color:#476044;padding:6px 8px;min-width:75px;cursor:pointer;transition:.15s}.upgrade-button:hover:not(:disabled){background:#e8eddc;border-color:#bbc9ad}.upgrade-button:disabled{opacity:.46;cursor:default}.upgrade-button span{display:block;font:7px 'DM Mono';letter-spacing:.3px;white-space:nowrap}.upgrade-button b{display:block;margin-top:2px;font:600 9px 'DM Sans';color:#ae8740}.gear-divider{height:1px;background:#eeeee9}.kit-note{display:flex;gap:7px;align-items:center;color:#889188;font-size:8px;padding:10px 0 0}.kit-note span:first-child{color:#b7944b;font-size:12px}.shoot-controls{margin-top:auto;background:#f1f2eb;padding:12px 14px 11px}.shoot-top{display:flex;justify-content:space-between;font:8px 'DM Mono';letter-spacing:.9px;color:#617060;margin-bottom:9px}.control-dot{width:6px;height:6px;display:inline-block;background:#8aa872;border-radius:50%;margin-right:5px;box-shadow:0 0 0 3px #8aa8721d}.arrows-left{color:#929a8f}.arrows-left span{color:#566a52}.shoot-button{width:100%;height:43px;background:#274e3e;border:0;color:#f6f6ed;position:relative;cursor:pointer;overflow:hidden;display:flex;justify-content:center;align-items:center;transition:background .15s,transform .15s}.shoot-button:hover{background:#315c47}.shoot-button:active{transform:scale(.99)}.shoot-label{font:600 10px 'DM Sans';letter-spacing:1.8px;position:relative;z-index:1}.shoot-key{position:absolute;right:13px;color:#cfda9e;font-size:16px;z-index:1}.button-shine{position:absolute;left:-30%;top:0;height:100%;width:30%;transform:skewX(-20deg);background:linear-gradient(90deg,transparent,#ffffff13,transparent);animation:shine 4s infinite}@keyframes shine{0%,55%{left:-40%}85%,100%{left:130%}}.shoot-tip{text-align:center;margin-top:8px;font:7px 'DM Mono';letter-spacing:.75px;color:#92998f}.shoot-tip span{padding:0 5px;color:#b2b9a3}.bottom-bar{height:45px;border-top:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;color:#a0a69d;font:8px 'DM Mono';letter-spacing:1px;flex:none}.bottom-bar b{color:#d1d1c5;font-weight:400;padding:0 3px}.bottom-bar span:nth-child(2){color:#9da398}.bottom-bar i{font-style:normal;color:#6b7c68}.bottom-bar button{border:0;background:none;color:#728173;font:8px 'DM Mono';letter-spacing:.8px;cursor:pointer;padding:7px 0}.bottom-bar button b{color:#a48c55;font-size:12px;padding-left:4px}.toast{position:fixed;left:50%;bottom:25px;transform:translate(-50%,20px);padding:10px 16px;background:#172d22;color:#eef0e5;font:10px 'DM Mono';letter-spacing:.5px;opacity:0;transition:.2s;pointer-events:none;z-index:5;box-shadow:0 4px 20px #192c2338}.toast.show{opacity:1;transform:translate(-50%,0)}.modal-backdrop{display:none;position:fixed;inset:0;background:#18251fc2;z-index:10;place-items:center;padding:18px}.modal-backdrop.open{display:grid}.modal{width:min(420px,100%);background:#fbfaf5;padding:29px;position:relative;box-shadow:0 20px 60px #10221866}.modal-close{position:absolute;right:16px;top:12px;border:0;background:none;font-size:24px;color:#829084;cursor:pointer}.modal h2{font:600 24px 'Playfair Display';margin:7px 0}.modal p{font-size:12px;line-height:1.6;color:#78837a;margin:0 0 17px}.area-list{display:flex;flex-direction:column;gap:7px}.area-option{display:grid;grid-template-columns:38px 1fr auto;align-items:center;gap:10px;padding:10px;border:1px solid #e8e8df;background:#fffefa;text-align:left;color:#25382d;cursor:pointer}.area-option:hover:not(:disabled){border-color:#a9b79b;background:#f5f6ef}.area-option:disabled{opacity:.55;cursor:default}.area-thumb{width:38px;height:35px;background:linear-gradient(155deg,#9bb19b 0 40%,#5f8068 41% 61%,#c6b995 62%);position:relative}.area-thumb:after{content:'';position:absolute;left:15px;top:7px;width:9px;height:11px;border-radius:50%;background:repeating-radial-gradient(circle,#f6f1dc 0 2px,#bd7453 2.5px 3px)}.area-option strong{display:block;font-size:11px}.area-option small{display:block;font:8px 'DM Mono';color:#8a948a;margin-top:3px}.area-price{font:9px 'DM Mono';color:#9c7941}.help-list{padding-left:17px;color:#66746a;font-size:11px;line-height:1.9}.help-list b{color:#304f3d}.modal-action{width:100%;height:39px;background:#274e3e;color:white;border:0;font:600 9px 'DM Sans';letter-spacing:1px;cursor:pointer;margin-top:12px}
@media (min-height:880px) and (min-width:850px){.game-shell{min-height:min(900px,calc(100dvh - 36px))}.game-layout{padding-top:32px;padding-bottom:29px}.scene-head{height:65px}.scene-wrap{min-height:450px}.side-panel{gap:16px}.card{padding:20px}.target-diagram{padding:13px 15px;margin-bottom:16px}.gear-card{padding:18px 20px 14px}.gear-row{padding:13px 0}.shoot-controls{padding:15px 16px 12px}}
@media (max-width:900px){body{padding:0;background:var(--paper)}.game-shell{min-height:100dvh;border:0;border-radius:0;padding:0 22px;box-shadow:none}.topbar{height:62px}.game-layout{grid-template-columns:minmax(0,1.5fr) minmax(285px,.9fr);gap:18px;padding:19px 0}.scene-head h1{font-size:24px}.side-panel{gap:10px}.card{padding:14px}.target-copy{margin:6px 0 10px}.target-diagram{padding:8px 10px;margin-bottom:10px}.mini-target{width:54px;height:54px}.gear-card{padding:14px}.gear-row{padding:9px 0}.bottom-bar{height:40px}}
@media (max-width:680px){body{display:block}.game-shell{padding:0 15px;min-height:100dvh}.topbar{height:56px}.brand-mark{width:28px;height:28px;font-size:17px}.brand-name{font-size:10px;letter-spacing:1.3px}.top-meta{gap:13px}.session-pill{font-size:8px;gap:6px}.session-pill .session-num{display:none}.coin-wallet{font-size:8px;gap:5px}.coin-wallet strong{font-size:15px}.coin-icon{font-size:17px}.game-layout{display:flex;flex-direction:column;gap:12px;padding:16px 0 14px}.scene-head{height:54px}.scene-head h1{font-size:23px;margin-top:3px}.area-switch{font-size:8px;height:29px;padding:0 7px;gap:5px}.scene-wrap{height:clamp(280px,43vh,440px);min-height:280px;flex:none}.distance-tag{top:12px;left:12px}.wind-widget{top:10px;right:10px;transform:scale(.87);transform-origin:top right}.range-caption{height:31px;font-size:7px}.caption-center{display:none}.side-panel{display:grid;grid-template-columns:1fr 1fr;gap:9px}.target-card{grid-column:1 / -1;padding:13px 14px}.card h2{font-size:17px}.target-copy{font-size:9px;max-width:unset;margin:6px 0 9px}.target-diagram{margin-bottom:9px;padding:7px 12px}.mini-target{height:51px;width:51px}.target-key{min-width:0;flex:1;margin-left:15px}.gear-card{padding:13px 11px;grid-column:1 / -1}.gear-head{margin-bottom:5px}.gear-row{grid-template-columns:29px minmax(75px,1fr) auto;gap:7px;padding:8px 0}.gear-icon{width:27px;height:27px}.gear-info strong{font-size:9px}.gear-info small{font-size:6px}.upgrade-button{min-width:65px;padding:5px 6px}.upgrade-button span{font-size:6px}.upgrade-button b{font-size:8px}.kit-note{font-size:7px;padding-top:7px}.shoot-controls{grid-column:1 / -1;margin-top:0;padding:11px 13px 9px}.shoot-button{height:42px}.bottom-bar{height:38px;font-size:7px}.bottom-bar span:nth-child(2){display:none}.scene-footer{font-size:7px}.scene-hint{bottom:34px}}
