.modal-action{width:100%;height:39px;background:#274e3e;color:white;border:0;font:600 9px 'DM Sans';letter-spacing:1px;cursor:pointer;margin-top:12px}

/* Release-to-shoot controls and clearer field readings */
.distance-tag{padding:7px 10px;background:#172a218c;border:1px solid #ffffff38;backdrop-filter:blur(4px)}
.wind-widget{box-shadow:0 6px 20px #14271d25}
.wind-status i{animation:wind-pulse 1.8s ease-in-out infinite}
@keyframes wind-pulse{50%{box-shadow:0 0 0 4px #c9dc7133}}
.scene-hint{padding:8px 12px;background:#172a218c;border:1px solid #ffffff38;backdrop-filter:blur(4px);letter-spacing:1px}
.scene-hint span{color:#dce89c}
.reload-icon{font-size:21px;color:#a27f43;background:#f4f0e2}
.reload-row .gear-info small{color:#8e856e}
.shoot-controls{border:1px solid #e6e8dc;transition:background .2s,border-color .2s}
.shoot-controls.reloading{background:#f4efe5;border-color:#e8dfc9}
.shoot-top b{font:inherit}
.shoot-controls.reloading .control-dot{background:#d39a50;box-shadow:0 0 0 3px #d39a501e;animation:reload-pulse 1s ease-in-out infinite}
@keyframes reload-pulse{50%{opacity:.45}}
.reload-countdown{font:7px 'DM Mono';letter-spacing:.7px;color:#8b927f}
.reload-meter{height:4px;background:#e1e4d8;overflow:hidden}
.reload-meter i{display:block;width:100%;height:100%;background:linear-gradient(90deg,#78916b,#c3cf7a);transform:scaleX(1);transform-origin:left center;transition:transform .12s linear}
.shoot-controls.reloading .reload-meter i{background:linear-gradient(90deg,#bd8d4e,#e0bd79)}
.shoot-tip{margin-top:9px;font-size:7px;letter-spacing:.85px;color:#657467}
.shoot-tip span{padding:0 3px;color:#b29c67}
@media (max-width:680px){.shoot-controls{padding:11px 13px 10px}.reload-row .gear-info small{letter-spacing:0}.distance-tag{padding:6px 8px}}
@media (prefers-reduced-motion:reduce){.wind-status i,.shoot-controls.reloading .control-dot{animation:none}}

