.aim-pad{position:absolute;z-index:5;right:14px;bottom:57px;width:104px;height:104px;border:1px solid #fff9;border-radius:50%;background:radial-gradient(circle,#30483aa8 0 34%,#172a218c 35% 100%);box-shadow:0 6px 20px #14271d45,inset 0 0 0 5px #ffffff12;touch-action:none;user-select:none;cursor:crosshair;backdrop-filter:blur(3px)}
